    fseek(fp, header_len + offset, SEEK_SET);
    size_t lazy_partial_len = BLOSC_EXTENDED_HEADER_LENGTH + nblocks * sizeof(int32_t);
    rbytes = fread(*chunk, 1, lazy_partial_len, fp);
    fclose(fp);
