    return -1;
  }

  if (new && schunk->cbytes > 0) {
    fprintf(stderr, "Error: new metalayers cannot be added after actual data has been appended\n");
    return -1;
  }

  if (frame->sdata == NULL) {
    size_t rbytes = 0;
    FILE* fp = fopen(frame->fname, "rb");
    if (fp != NULL) {
      rbytes = fread(header, 1, FRAME_HEADER_MINLEN, fp);
      fclose(fp);
    }
    (void) rbytes;
